/**
 * world-decisions: keeps each project's user decisions and picked art in front of every agent.
 *
 * Source: <workspace>/<project>/DECISIONS.json + DECISIONS.md, generated by `.omp/scripts/steer.py`
 * from the project's STEER.jsonl decision database. Runs in the main session and in every subagent.
 *
 * - First time a session works on a project (its name in the prompt, the cwd, a tool call's path or a
 *   Unity instance `Name@hash`), the decision digest is injected: the whole DECISIONS.md when small,
 *   otherwise the binding rules, the picked and rejected art and a one-line index of every decision.
 * - When DECISIONS.json changes mid-session, only the new records are injected.
 * - A tool call that mentions a record's `targets` (Fumo_*, FumoScream.cs, a scene path ...) gets that
 *   record's full text as a reminder, at most once every REMIND_EVERY tool calls per record.
 * - Compaction keeps a pointer to the digests and re-arms the injection.
 *
 * Why (user, 2026-11-05): agents forgot picked concept art and earlier user decisions, and a skill
 * default (pickups with gravity) silently overrode the user's "fumos should not be affected by gravity".
 */
import * as fs from "node:fs";
import * as path from "node:path";

const ROOT = path.resolve(
	path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1")),
	"..", "..", "..",
);
const FULL_DIGEST_MAX = 16_000;
const REMIND_EVERY = 25;
const MAX_REMINDERS = 6;

interface Rec {
	id: string;
	when: string;
	topic: string;
	affects: string[];
	aspect: string[];
	targets: string[];
	pick: string;
	decision: string;
	said: string;
	images: string[];
	status: string;
}
interface Db {
	project: string;
	generated: string;
	records: Rec[];
}

let projectCache: { at: number; names: string[] } = { at: 0, names: [] };
function projects(): string[] {
	if (Date.now() - projectCache.at < 30_000) return projectCache.names;
	let names: string[] = [];
	try {
		names = fs
			.readdirSync(ROOT, { withFileTypes: true })
			.filter(d => d.isDirectory() && fs.existsSync(path.join(ROOT, d.name, "DECISIONS.json")))
			.map(d => d.name);
	} catch {
		// Workspace unreadable: no projects.
	}
	projectCache = { at: Date.now(), names };
	return names;
}

function loadDb(name: string): Db | undefined {
	try {
		return JSON.parse(fs.readFileSync(path.join(ROOT, name, "DECISIONS.json"), "utf8")) as Db;
	} catch {
		return undefined;
	}
}

const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const NAME_CHARS = "A-Za-z0-9_\\-";

function mentioned(text: string, cwd: string | undefined): string[] {
	const out: string[] = [];
	const rel = cwd ? path.relative(ROOT, cwd) : "";
	const cwdProject = rel && !rel.startsWith("..") && !path.isAbsolute(rel) ? rel.split(/[\\/]/)[0] : "";
	for (const n of projects()) {
		const re = new RegExp(`(^|[^${NAME_CHARS}])${esc(n)}([^${NAME_CHARS}]|$)`, "i");
		if (n === cwdProject || re.test(text)) out.push(n);
	}
	return out;
}

function targetRegex(glob: string): RegExp {
	const body = glob
		.split("*")
		.map(esc)
		.join("[A-Za-z0-9_.\\-/]*");
	return new RegExp(`(?<![A-Za-z0-9])${body}`, "i");
}

function recLine(r: Rec, full: boolean): string {
	const labels = `${r.aspect.join(", ") || "no aspect"} · ${r.affects.join(", ")}`;
	const decision = full || r.decision.length <= 160 ? r.decision : `${r.decision.slice(0, 157)}…`;
	const imgs = full && r.images.length ? `\n  images: ${r.images.join(" ; ")}` : "";
	const said = full ? ` — user: ${r.said}` : "";
	return `- [${r.id}] ${r.topic} (${labels}): ${decision}${said}${imgs}`;
}

const RULES =
	"Binding: these are the user's own decisions for this project. They override workspace defaults, skill defaults " +
	"and briefs. Before working on a part of the world, read its decisions and open the picked art for it. If a task " +
	"would contradict a decision, stop and ask the user (quiet hours: skip that item and report it). Record every new " +
	"user decision before acting on it: `python .omp/scripts/steer.py --project <project> add|pick ...` with the " +
	"user's exact words. Pass the relevant decisions (and picked image paths) into every subagent brief.";

function digest(db: Db): string {
	const md = path.join(ROOT, db.project, "DECISIONS.md");
	let text = "";
	try {
		text = fs.readFileSync(md, "utf8");
	} catch {
		// Fall through to the index form.
	}
	if (text && text.length <= FULL_DIGEST_MAX) {
		return `<world-decisions project="${db.project}" file="${md}">\n${text}\n</world-decisions>`;
	}
	const liked = db.records.filter(r => r.pick === "liked");
	const rejected = db.records.filter(r => r.pick === "rejected");
	const rest = db.records.filter(r => !r.pick);
	const parts = [
		`<world-decisions project="${db.project}" file="${md}">`,
		RULES,
		`Full text of every decision: ${md} (read the sections for the parts you work on).`,
	];
	if (liked.length) parts.push("Art the user picked (build to these):", ...liked.map(r => recLine(r, true)));
	if (rejected.length) parts.push("Art the user rejected (never build like these):", ...rejected.map(r => recLine(r, true)));
	if (rest.length) parts.push("Decisions in force (index):", ...rest.map(r => recLine(r, false)));
	parts.push("</world-decisions>");
	return parts.join("\n");
}

interface Ctx {
	cwd?: string;
}
interface Api {
	on(event: string, handler: (event: { prompt?: unknown; input?: unknown }, ctx: Ctx) => Promise<unknown>): void;
}

export default function worldDecisions(pi: Api): void {
	// Per-session state: the factory is rebound for every session and subagent.
	const seen = new Map<string, { generated: string; ids: Set<string> }>();
	const remindedAt = new Map<string, number>();
	let calls = 0;

	function inject(names: string[]): string[] {
		const out: string[] = [];
		for (const n of names) {
			const db = loadDb(n);
			if (!db) continue;
			const prev = seen.get(n);
			if (!prev) {
				out.push(digest(db));
			} else if (prev.generated !== db.generated) {
				const fresh = db.records.filter(r => !prev.ids.has(r.id));
				if (fresh.length) {
					out.push(
						`<world-decisions project="${n}" update="true">\nNew user decisions recorded for ${n} (binding):\n` +
							`${fresh.map(r => recLine(r, true)).join("\n")}\n</world-decisions>`,
					);
				}
			} else {
				continue;
			}
			seen.set(n, { generated: db.generated, ids: new Set(db.records.map(r => r.id)) });
		}
		return out;
	}

	function reminders(text: string): string[] {
		const scope = seen.size ? [...seen.keys()] : projects();
		const hits: string[] = [];
		for (const n of scope) {
			const db = loadDb(n);
			if (!db) continue;
			for (const r of db.records) {
				if (!r.targets?.length || hits.length >= MAX_REMINDERS) continue;
				const key = `${n}:${r.id}`;
				const last = remindedAt.get(key);
				if (last !== undefined && calls - last < REMIND_EVERY) continue;
				if (!r.targets.some(t => targetRegex(t).test(text))) continue;
				remindedAt.set(key, calls);
				hits.push(`${n} ${recLine(r, true)}`);
			}
		}
		if (!hits.length) return [];
		return [
			"<world-decisions reminder=\"true\">\nThis call touches things the user decided about. Follow these over any " +
				`default, skill or brief:\n${hits.join("\n")}\n</world-decisions>`,
		];
	}

	pi.on("before_agent_start", async (event, ctx) => {
		const prompt = typeof event?.prompt === "string" ? event.prompt : "";
		const blocks = inject(mentioned(prompt, ctx?.cwd));
		if (!blocks.length) return;
		return {
			message: { customType: "world-decisions", content: blocks.join("\n\n"), display: false },
		};
	});

	pi.on("tool_call", async (event, ctx) => {
		calls++;
		let text = "";
		try {
			text = JSON.stringify(event?.input ?? {});
		} catch {
			return;
		}
		const blocks = [...inject(mentioned(text, ctx?.cwd)), ...reminders(text)];
		if (blocks.length) return { additionalContext: blocks.join("\n\n") };
	});

	pi.on("session.compacting", async () => {
		if (!seen.size) return;
		return {
			context: [
				"World decisions in force (binding user decisions and picked art; re-read before continuing): " +
					[...seen.keys()].map(n => `${n} -> ${path.join(ROOT, n, "DECISIONS.md")}`).join("; "),
			],
		};
	});

	pi.on("session_compact", async () => {
		seen.clear();
		remindedAt.clear();
	});
}
